            // 仅触发一次的事件在触发后，再次添加监听方法时，会被立即执行
            this._notify(s, this.firedWith);
        }

        if (when == AFTER) {
            this.afters[s.id] = s;
            this.afterCount++;
        } else {
            this.subscribers[s.id] = s;
            this.subCount++;
        }

        return new Y.EventHandle(this, s);
    },

    // 触发事件
    fire: function () {
        if (this.fireOnce &amp;&amp; this.fired) {
            // 仅触发一次的事件，如果已经触发过，直接返回true
            return true;
        } else {
            // 可以设置参数，传给回调函数
            var args = Y.Array(arguments, 0, true);

            this.fired = true;
            this.firedWith = args;

            if (this.emitFacade) {
                // 复杂事件
                return this.fireComplex(args);
            } else {
                return this.fireSimple(args);
            }
        }
    },
    // 触发简单事件
    fireSimple: function (args) {
        this.stopped = 0;
        this.prevented = 0;
        if (this.hasSubs()) {
            var subs = this.getSubs();
            // 处理前置监听对象
            this._procSubs(subs[0], args);
            // 处理前置监听对象
            this._procSubs(subs[1], args);
        }
        this._broadcast(args);
        return this.stopped ? false : true;
    },
    // 判断是否有监听对象
    hasSubs: function (when) {
        var s = this.subCount,
            a = this.afterCount;
        if (when) {
            return (when == 'after') ? a : s;
        }
        return (s + a);
    },
    // 获取所有前置／后置监听对象
    getSubs: function () {
        var s = Y.merge(this.subscribers),
            a = Y.merge(this.afters);
        return [s, a];
    },
    // 获取监听对象
    _procSubs: function (subs, args, ef) {
        var s, i;
        for (i in subs) {
            if (subs.hasOwnProperty(i)) {
                s = subs[i];
                if (s && s.fn) {
                    if (false === this._notify(s, args, ef)) {
                        // 回调返回false时，立即停止处理后续回调
                        this.stopped = 2;
                    }
                    if (this.stopped == 2) {
                        // 立即停止处理后续回调，方便实现stopImmediatePropagation
                        return false;
                    }
                }
            }
        }

        return true;
    },
    // 通知监听对象，执行回调方法
    _notify: function (s, args, ef) {
        var ret = s.notify(args, this);
        if (false === ret || this.stopped &gt; 1) {
            return false;
        }
        return true;
    },
    // 广播事件
    _broadcast: function (args) {
        if (!this.stopped &amp;&amp; this.broadcast) {
            var a = Y.Array(args);
            a.unshift(this.type);

            // 在当前YUI实例Y上广播
            if (this.host !== Y) {
                Y.fire.apply(Y, a);
            }

            // 在全局对象YUI上广播，跨实例
            if (this.broadcast == 2) {
                Y.Global.fire.apply(Y.Global, a);
            }
        }
    },

    // TODO: 在下一篇介绍Y.EventTarget的文章中再做介绍
    fireComplex: function (args) {},

    // 移除监听器
    detach: function (fn, context) {
        // unsubscribe handle
        if (fn &amp;&amp; fn.detach) {
            return fn.detach();
        }

        var i, s,
            found = 0,
            subs = Y.merge(this.subscribers, this.afters);

        for (i in subs) {
            if (subs.hasOwnProperty(i)) {
                s = subs[i];
                if (s &amp;&amp; (!fn || fn === s.fn)) {
                    this._delete(s);
                    found++;
                }
            }
        }

        return found;
    },
    _delete: function (s) {
        if (s) {
            if (this.subscribers[s.id]) {
                delete this.subscribers[s.id];
                this.subCount--;
            }
            if (this.afters[s.id]) {
                delete this.afters[s.id];
                this.afterCount--;
            }
        }

        if (s) {
            s.deleted = true;
        }
    }
};
```

### 适用场景
自定义事件的适用场景与Publish–subscribe Pattern基本一致。具体来讲，我觉得以下一些场景是非常适合用自定义事件的：

#### a) 需要暴露接口/行为以满足扩展需要

底层模块一般会设计的尽量简单，解决核心问题，并适当的开放一些接口，方便应用层进行扩展以满足实际需求。例如表单验证控件，有可能需要在某个表单项验证成功/失败后执行一些额外操作，举一个实际的例子：当用户输入的邮箱地址验证成功时，我们会检查是不是某些比较烂的邮件服务商，如果是则给出一些建议。

YUI作为一个底层基础库，在组件/控件层面加入了大量的自定义事件，以满足实际应用中的需要。例如`Y.Anim`的start、end事件，`Y.io`的success、failure、end事件，`Y.Attribute`中的属性变化事件等。

#### b) 行为可能会被其它模块/方法中止

这一点非常像DOM事件，我们经常会中止一些事件的默认行为，例如anchor的点击事件。

### 自定义事件 VS 回调函数

这是一个比较难的问题，我自己的看法是：相对回调函数，自定义事件是一种更重但更灵活的方案。在实际应用中，如果对于关心某消息的受众不够清楚，那么就使用事件。否则，比较适合使用回调函数。

[MSDN](http://msdn.microsoft.com/en-us/library/aa733743%28v=vs.60%29.aspx)上的解释更好一些：“An event is like an anonymous broadcast, while a call-back is like a handshake. The corollary of this is that a component that raises events knows nothing about its clients, while a component that makes call-backs knows a great deal”。

另外，如果对于性能特别关心，在可能的情况下，尽量使用回调。

## 参考
- [YUILibrary-CustomEvent](http://yuilibrary.com/yui/docs/api/files/event-custom_js_event-custom.js.html)
- [YUILibrary-EventTarget](http://yuilibrary.com/yui/docs/event-custom/index.html)
- [Wikipedia-Publish–subscribe Pattern](http://en.wikipedia.org/wiki/Publish%E2%80%93subscribe_pattern)
- [Zakas-Custom events in JavaScript](http://www.nczonline.net/blog/2010/03/09/custom-events-in-javascript/)
- [When to Use Events or Call-Backs for Notifications][1]

[1]:http://msdn.microsoft.com/en-us/library/aa733743(v=vs.60).aspx

Post._content:
![relay baton](/images/delegate.jpg)

在介绍了YUI自定义事件体系和对DOM事件的封装后，本篇文章重点阐述事件方面的一种常用技术——事件代理。事件代理（Event Delegation，又称事件委托）充分运用事件传播模型，用一种十分优雅的方式实现了批量节点事件监听。具体的原理和优点请移步zakas比较古老的一篇文章[Event delegation in JavaScript](http://www.nczonline.net/blog/2009/06/30/event-delegation-in-javascript/)。事件代理在YUI中的实现为`Y.delegate`。

## 基本用法

为方便讨论，约定以下名称：

- 代理节点：实际监听事件的节点。在事件传播到此节点时判断是否符合代理条件，符合则执行回调函数。
- 被代理节点：希望监听事件的节点。如果不采用事件代理，那么应该直接监听这些节点的事件。
- 目标节点：事件发生的目标节点，即`event.target`。

三者的层次关系从内到外依次为：目标节点 &lt;= 被代理节点 &lt;= 代理节点。

<!-- more -->

假设html为：

```html
<ul>
    <li>
        <a href="http://google.com">google</a>
    </li>
    <li>
        <a name="facebook" href="http://facebook.com">facebook</a>
    </li>
    <li>
        <a name="twitter" href="http://twitter.com">twitter</a>
    </li>
</ul>
```

先来看下`Y.delegate`的简单用法：

```js
// 例1
// API: Y.delegate(type, fn, el, filter)
YUI().use('event-delegate', function(Y) {
    var handle = Y.delegate('click', function (e) {
        e.halt();
        console.log(this.get('tagName') + ' is clicked');
    }, 'ul', 'a');

    Y.delegate('click', function (e) {
        console.log(this.get('tagName') + ' is clicked');
    }, 'ul', 'li');

    // click first anchor
    // output 'A is clicked'
    // output 'LI is clicked'

    handle.detach();

    // click first anchor again
    // output 'LI is clicked'
});
```

可以看出，回调函数中的this指向的是使用`Y.Node`包装的被代理节点。

YUI3新加入的`Y.Node`对象也封装了delegate，例1更常见的实现如下：

```js
// 例2
// API: Y.Node.prototype.delegate(type, fn, filter)
YUI().use('node-event-delegate', function(Y) {
    var ndList = Y.one('ul'),
        handle;

    handle = ndList.delegate('click', function (e) {
        e.halt();
        console.log(this.get('tagName') + ' is clicked');
    }, 'a');

    ndList.delegate('click', function (e) {
        console.log(this.get('tagName') + ' is clicked');
    }, 'li');

    // click first anchor
    // output 'A is clicked'
    // output 'LI is clicked'

    handle.detach();

    // click first anchor again
    // output 'LI is clicked'
});
```

筛选条件除了例1中使用的selector外，还支持函数：

```js
// 例3
YUI().use('node-event-delegate', function(Y) {
    var ndList = Y.one('ul');

    ndList.delegate('click', function (e) {
        e.halt();
        console.log(this.get('tagName') + ' is clicked');
    }, function (nd, e) {
        return nd.get('name') &&
               e.target.get('tagName').toLowerCase() === 'a';
    });

    // click the first anchor
    // no output

    // click the second anchor
    // output 'LI is clicked'
});
```

## 源码分析

接下来，让我们看看YUI的内部实现吧。

注：为了更容易的看懂代码的核心，我做了适当的简化，感兴趣的朋友可以去看未删节的[源码](https://github.com/yui/yui3/blob/v3.9.1/src/event/js/delegate.js)。

```js
var toArray = Y.Array,
    isString = Y.Lang.isString;

function delegate(type, fn, el, filter) {
    var container = isString(el) ? Y.Selector.query(el, null, true) : el,
        handle;

    // 监听代理节点的type事件
    handle = Y.Event._attach([type, fn, container], { facade: false });
    handle.sub.filter  = filter;
    // 改写事件触发回调函数
    handle.sub._notify = delegate.notifySub;

    return handle;
}

// 代理节点触发事件时的回调函数
delegate.notifySub = function (thisObj, args, ce) {
    // 计算符合filter的被代理节点集合
    var currentTarget = delegate._applyFilter(this.filter, args, ce),
        e, i, len, ret;
    if (!currentTarget) return;

    currentTarget = toArray(currentTarget);

    // 生成事件对象
    e = args[0] = new Y.DOMEventFacade(args[0], ce.el, ce);
    // 将代理节点保存在事件对象container属性上，方便回调函数调用
    e.container = Y.one(ce.el);

    for (i = 0, len = currentTarget.length; i < len && !e.stopped; ++i) {
        // 将被代理节点保存在事件对象currentTarget属性上
        e.currentTarget = Y.one(currentTarget[i]);

        // 回调函数中的this指向被代理节点
        ret = this.fn.apply(e.currentTarget, args);
        if (ret === false) break;
    }

    return ret;
};

// 计算符合filter的被代理节点集合
delegate._applyFilter = function (filter, args, ce) {
    var e         = args[0],
        container = ce.el,
        target    = e.target || e.srcElement,
        match     = [],
        isContainer = false;

    // 处理事件目标节点为文本节点的情况
    if (target.nodeType === 3) {
        target = target.parentNode;
    }

    // filter是selector
    if (isString(filter)) {
        while (target) {
            isContainer = (target === container);
            // 测试target是否符合selector filter
            if (Y.Selector.test(target, filter, (isContainer ? null : container))) {
                match.push(target);
            }
            if (isContainer) break;

            target = target.parentNode;
        }
    // filter是function
    } else {
        // 将target节点作为function filter的第一个参数，
        // 第二个参数为事件对象
        args.unshift(Y.one(target));
        args[1] = new Y.DOMEventFacade(e, container, ce);

        while (target) {
            // function filter中this指向target
            if (filter.apply(args[0], args)) {
                match.push(target);
            }
            if (target === container) break;

            // 更新target
            target = target.parentNode;
            args[0] = Y.one(target);
        }

        // 恢复args对象
        args[1] = e;
        args.shift();
    }

    return match.length <= 1 ? match[0] : match;
};

Y.delegate = Y.Event.delegate = delegate;
```

## 进阶用法

### 批量代理

`Y.delegate`支持同时代理多种类型的事件，调用方式有如下两种：

- Y.delegate({ typeA: fnA, typeB: fnB }, el, filter)
- Y.delegate([typeA, typeB], fn, el, filter)

```js
// 例4
YUI().use('node-event-delegate', function(Y) {
    var ndList = Y.one('ul');
    ndList.delegate({
        click: function (e) {
            e.halt();
            console.log(e.type);
        },
        dblclick: function (e) {
            e.halt();
            console.log(e.type);
        }
    }, 'li');

    // double click the first anchor
    // output 'click'
    // output 'click'
    // output 'dblclick'

    ndList.delegate(['click', 'dblclick'], function (e) {
        e.halt();
        console.log(e.type);
    }, 'li');

    // double click the first anchor
    // output 'click'
    // output 'click'
    // output 'dblclick'
});
```

### 修改回调函数this，传递数据

```js
// 例5
YUI().use('node-event-delegate', function(Y) {
    Y.one('ul').delegate('click', function (e, args) {
        e.halt();
        console.log(this === document.body);
        console.log(args.data);
    }, 'li', document.body, { data: 'data' });

    // click the first anchor
    // output 'true'
    // output 'data'
});
```

### focus、blur事件的代理

在DOM规范中，诸如focus、blur、load、unload、resize等事件是不冒泡的，因为这类事件只限定在某个节点上触发。但focus和blur事件有些特殊，在表单交互方面十分常用，如果能够支持冒泡，那么通过事件代理可以减少很多监听事件的操作。滑稽的是，focusin、focusout两个类似的事件却支持冒泡。

令人欣喜的是，YUI通过定义新的DOM事件实现了focus、blur事件的代理，awesome！

```js
// 例6
YUI().use('node-event-delegate', 'event-focus', function(Y) {
    Y.one('form').delegate({
        focus: function (e) {
            // 清除错误提示
            clearErr(this);
        },
        blur: function (e) {
            // 如果内容为空，则提示错误信息
            if (this.get('value') === '') showErr(this);
        }
    }, 'input');

    function clearErr(nd) {
        var ndErr = nd.next('.error');
        if (ndErr) ndErr.hide().setHTML('');
    };

    function showErr(nd) {
        var ndErr = nd.next('.error');
        if (!ndErr) {
            ndErr = Y.Node.create('<span class="error"></span>');
            nd.insert(ndErr, 'after');
        }

        ndErr.show().setHTML('请输入内容');
    };
});
```

## 示例代码

所有示例代码均在[GitHub](https://github.com/springuper/yuianalyser/tree/master/event)。

## 参考

- [YUILibrary-UserGuides-Event Delegation](http://yuilibrary.com/yui/docs/event/#delegation)
- [Event delegation in JavaScript](http://www.nczonline.net/blog/2009/06/30/event-delegation-in-javascript/)
- [YUILibrary-delegate](https://github.com/yui/yui3/blob/v3.9.1/src/event/js/delegate.js)

