                        cewrapper.nodeRef = cewrapper.nodeRef || Y.one(cewrapper.el);
                        return cewrapper.nodeRef;
                    }
                });

                cewrapper.overrides = {};

                cewrapper.el = el;
                cewrapper.key = key;
                cewrapper.domkey = ek;
                cewrapper.type = type;
                // 作为原生DOM事件回调
                cewrapper.fn = function (e) {
                    // 触发事件，回调方法可以直接调用作为第一个参数的
                    // DOM事件包装对象
                    cewrapper.fire(Event.getEvent(e, el));
